pub(crate) fn rules_has(rules: &[BoundsRule], owner: &str, kind: &str, a: &str, b: &str) -> bool {
    for rule in rules.iter() { if rule.owner == owner && rule.kind == kind && rule.a == a && rule.b == b { return true; } }
    false
}

pub(crate) fn rules_together(methods: &[collections::BTreeSet<String>], a: &str, b: &str) -> bool {
    for lengths in methods.iter() { if lengths.contains(a) != lengths.contains(b) { return false; } }
    true
}

